import{_ as s,a0 as p,w as a,s as l,I as t,x as e,a1 as o,A as m,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"《代碼英雄》第一季（1）：操作系統戰爭（上） | LCTT x X-CMD","titleTemplate":false,"description":"《代碼英雄》第一季（1）：操作系統戰爭（上） | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"《代碼英雄》第一季（1）：操作系統戰爭（上） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"《代碼英雄》第一季（1）：操作系統戰爭（上） | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20180116 Command Line Heroes- Season 1- OS Wars","title":"《代碼英雄》第一季（1）：操作系統戰爭（上）","tag":"201908","desc":""},"relativePath":"201908/20180116 Command Line Heroes- Season 1- OS Wars.md","filePath":"[post].md"}'),i={name:"201908/20180116 Command Line Heroes- Season 1- OS Wars.md"};function g(b,r,d,S,y,L){const n=p("Link");return a(),l("div",null,[r[27]||(r[27]=t("h1",{id:"《代碼英雄》第一季-1-操作系統戰爭-上",tabindex:"-1"},[e("《代碼英雄》第一季（1）：操作系統戰爭（上） "),t("a",{class:"header-anchor",href:"#《代碼英雄》第一季-1-操作系統戰爭-上","aria-label":"Permalink to “《代碼英雄》第一季（1）：操作系統戰爭（上）”"},"​")],-1)),r[28]||(r[28]=t("blockquote",null,[t("p",null,"代碼英雄講述了開發人員、程序員、黑客、極客和開源反叛者如何徹底改變技術前景的真實史詩故事。")],-1)),r[29]||(r[29]=t("p",null,[t("img",{src:"https://www.redhat.com/files/webux/img/bandbg/bkgd-clh-ep1-2000x950.png",alt:""})],-1)),t("p",null,[r[3]||(r[3]=e("本文是《",-1)),o(n,{href:"https://www.redhat.com/en/command-line-heroes"},{default:m(()=>[...r[0]||(r[0]=[e("代碼英雄",-1)])]),_:1}),r[4]||(r[4]=e("》系列播客",-1)),o(n,{href:"https://www.redhat.com/en/command-line-heroes/season-1/os-wars-part-1"},{default:m(()=>[...r[1]||(r[1]=[e("第一季（1）：操作系統戰爭（上）",-1)])]),_:1}),r[5]||(r[5]=e(" 的",-1)),o(n,{href:"https://dts.podtrac.com/redirect.mp3/audio.simplecast.com/f7670e99.mp3"},{default:m(()=>[...r[2]||(r[2]=[e("音頻",-1)])]),_:1}),r[6]||(r[6]=e("腳本。",-1))]),r[30]||(r[30]=u("<p><strong>Saron Yitbarek：</strong>有些故事如史詩般，驚險萬分，在我腦海中似乎出現了星球大戰電影開頭的爬行文字。你知道的，就像——</p><p>配音：“第一集，操作系統大戰”</p><p><strong>Saron Yitbarek：</strong>是的，就像那樣子。</p><p>配音：這是一個局勢緊張加劇的時期。<ruby>比爾·蓋茨<rt>Bill Gates</rt></ruby>與<ruby>史蒂夫·喬布斯<rt>Steve Jobs</rt></ruby>的帝國發起了一場無可避免的專有軟件之戰。[00:00:30] 蓋茨與 IBM 結成了強大的聯盟，而喬布斯則拒絕了對它的硬件和操作系統開放授權。他們爭奪統治地位的爭鬥在一場操作系統戰爭中席捲了整個銀河系。與此同時，這些帝王們所不知道的偏遠之地，開源的反叛者們開始集聚。</p><p><strong>Saron Yitbarek：</strong>好吧。這也許有點戲劇性，但當我們談論上世紀八九十年代和 2000 年代的操作系統之爭時，這也不算言過其實。<em>[00:01:00]</em> 確實曾經發生過一場史詩級的統治之戰。史蒂夫·喬布斯和比爾·蓋茨確實掌握着數十億人的命運。掌控了操作系統，你就掌握了絕大多數人使用計算機的方式、互相通訊的方式、獲取信息的方式。我可以一直羅列下去，不過你知道我的意思。掌握了操作系統，你就是帝王。</p><p>我是 Saron Yitbarek，你現在收聽的是代碼英雄，一款紅帽公司原創的Blog節目。<em>[00:01:30]</em> 你問，什麼是<ruby>代碼英雄<rt>Command Line Hero</rt></ruby>？嗯，如果你願意創造而不僅僅是使用，如果你相信開發者擁有構建美好未來的能力，如果你希望擁有一個大家都有權利表達科技如何塑造生活的世界，那麼你，我的朋友，就是一位代碼英雄。在本系列節目中，我們將為你帶來那些“白碼起家”（LCTT 譯註：原文是 “from the command line up”，應該是演繹自 “from the ground up”——白手起家）改變技術的程序員故事。<em>[00:02:00]</em> 那麼我是誰，憑什麼指導你踏上這段艱苦的旅程？Saron Yitbarek 是哪根葱？嗯，事實上我覺得我跟你差不多。我是一名面向初學者的開發人員，我做的任何事都依賴於開源軟件，我的世界就是如此。通過在Blog中講故事，我可以跳出無聊的日常工作，鳥瞰全景，希望這對你也一樣有用。</p><p>我迫不及待地想知道，開源技術從何而來？我的意思是，我對<ruby>林納斯·託瓦茲<rt>Linus Torvalds</rt></ruby>和 Linux^® 的榮耀有一些瞭解，<em>[00:02:30]</em> 我相信你也一樣，但是説真的，開源並不是一開始就有的，對嗎？如果我想發自內心的感激這些最新、最棒的技術，比如 DevOps 和容器之類的，我感覺我對那些早期的開發者缺乏瞭解，我有必要了解這些東西來自何處。所以，讓我們暫時先不用擔心內存泄露和緩衝溢出。我們的旅程將從操作系統之戰開始，這是一場波瀾壯闊的桌面控制之戰。<em>[00:03:00]</em> 這場戰爭亙古未有，因為：首先，在計算機時代，大公司擁有指數級的規模優勢；其次，從未有過這麼一場控制爭奪戰是如此變化多端。比爾·蓋茨和史蒂夫·喬布斯? 他們也不知道結果會如何，但是到目前為止，這個故事進行到一半的時候，他們所爭奪的所有東西都將發生改變、進化，最終上升到雲端。</p><p><em>[00:03:30]</em> 好的，讓我們回到 1983 年的秋季。還有六年我才出生。那時候的總統還是<ruby>羅納德·里根<rt>Ronald Reagan</rt></ruby>，美國和蘇聯揚言要把地球拖入核戰爭之中。在檀香山（火奴魯魯）的市政中心正在舉辦一年一度的蘋果公司銷售會議。一羣蘋果公司的員工正在等待史蒂夫·喬布斯上台。他 28 歲，熱情洋溢，看起來非常自信。喬布斯很嚴肅地對着麥克風説他邀請了三個行業專家來就軟件進行了一次小組討論。<em>[00:04:00]</em> 然而隨後發生的事情你肯定想不到。超級俗氣的 80 年代音樂響徹整個房間。一堆多彩燈管照亮了舞台，然後一個播音員的聲音響起-</p><p><strong>配音：</strong>女士們，先生們，現在是麥金塔軟件的約會遊戲時間。</p><p><strong>Saron Yitbarek：</strong>喬布斯的臉上露出一個大大的笑容，台上有三個 CEO 都需要輪流向他示好。這基本上就是 80 年代鑽石王老五，不過是科技界的。<em>[00:04:30]</em> 兩個軟件大佬講完話後，然後就輪到第三個人講話了。僅此而已不是嗎？是的。新面孔比爾·蓋茨帶着一個大大的遮住了半張臉的方框眼鏡。他宣稱在 1984 年，微軟的一半收入將來自於麥金塔軟件。他的這番話引來了觀眾熱情的掌聲。<em>[00:05:00]</em> 但是他們不知道的是，在一個月後，比爾·蓋茨將會宣佈發佈 Windows 1.0 的計劃。你永遠也猜不到喬布斯正在跟蘋果未來最大的敵人打情罵俏。但微軟和蘋果即將經歷科技史上最糟糕的婚禮。他們會彼此背叛、相互毀滅，但又深深地、痛苦地捆綁在一起。</p><p><strong>James Allworth：</strong><em>[00:05:30]</em> 我猜從哲學上來講，一個更理想化、注重用户體驗高於一切，是一個一體化的組織，而微軟則更務實，更模組化 ——</p><p><strong>Saron Yitbarek：</strong>這位是 James Allworth。他是一位多產的科技作家，曾在蘋果零售的企業團隊工作。注意他給出的蘋果的定義，一個一體化的組織，那種只對自己負責的公司，一個不想依賴別人的公司，這是關鍵。</p><p><strong>James Allworth：</strong><em>[00:06:00]</em> 蘋果是一家一體化的公司，它希望專注於令人愉悦的用户體驗，這意味着它希望控制整個技術棧以及交付的一切內容：從硬件到操作系統，甚至運行在操作系統上的應用程序。當新的創新、重要的創新剛剛進入市場，而你需要橫跨軟硬件，並且能夠根據自己意願和軟件的革新來改變硬件時，這是一個優勢。例如 ——，</p><p><strong>Saron Yitbarek：</strong><em>[00:06:30]</em> 很多人喜歡這種一體化的模式，並因此成為了蘋果的鐵桿粉絲。還有很多人則選擇了微軟。讓我們回到檀香山的銷售會議上，在同一場活動中，喬布斯向觀眾展示了他即將發佈的超級碗廣告。你可能已經親眼見過這則廣告了。想想<ruby>喬治·奧威爾<rt>George Orwell</rt></ruby>的 《一九八四》。在這個冰冷、灰暗的世界裏，無意識的機器人正在獨裁者的投射凝視下徘徊。<em>[00:07:00]</em> 這些機器人就像是 IBM 的用户們。然後，代表蘋果公司的漂亮而健美的<ruby>安婭·梅傑<rt>Anya Major</rt></ruby>穿着鮮豔的衣服跑過大廳。她向着大佬們的屏幕猛地投出大錘，將它砸成了碎片。老大哥的咒語解除了，一個低沉的聲音響起，蘋果公司要開始介紹麥金塔了。</p><p><strong>配音：</strong>這就是為什麼現實中的 1984 跟小説《一九八四》不一樣了。</p><p>Saron Yitbarek：是的，現在回顧那則廣告，認為蘋果是一個致力於解放大眾的自由鬥士的想法有點過分了。但這件事觸動了我的神經。<em>[00:07:30]</em> Ken Segal 曾在為蘋果製作這則廣告的廣告公司工作過。在早期，他為史蒂夫·喬布斯做了十多年的廣告。</p><p><strong>Ken Segal：</strong>1984 這則廣告的風險很大。事實上，它的風險太大，以至於蘋果公司在看到它的時候都不想播出它。你可能聽説了史蒂夫喜歡它，但蘋果公司董事會的人並不喜歡它。事實上，他們很憤怒，這麼多錢被花在這麼一件事情上，以至於他們想解僱廣告代理商。<em>[00:08:00]</em> 史蒂夫則為我們公司辯護。</p><p><strong>Saron Yitbarek：</strong>喬布斯，一如既往地，慧眼識英雄。</p><p><strong>Ken Segal：</strong>這則廣告在公司內、在業界內都引起了共鳴，成為了蘋果產品的代表。無論人們那天是否有在購買電腦，它都帶來了一種持續了一年又一年的影響，並有助於定義這家公司的品質：我們是叛軍，我們是拿着大錘的人。</p><p><strong>Saron Yitbarek：</strong><em>[00:08:30]</em> 因此，在爭奪數十億潛在消費者心智的過程中，蘋果公司和微軟公司的帝王們正在學着把自己塑造成救世主、非凡的英雄、一種對生活方式的選擇。但比爾·蓋茨知道一些蘋果難以理解的事情。那就是在一個相互連接的世界裏，沒有人，即便是帝王，也不能獨自完成任務。</p><p><em>[00:09:00]</em> 1985 年 6 月 25 日。蓋茨給當時的蘋果 CEO John Scully 發了一份備忘錄。那是一個迷失的年代。喬布斯剛剛被逐出公司，直到 1996 年才回到蘋果。也許正是因為喬布斯離開了，蓋茨才敢寫這份東西。在備忘錄中，他鼓勵蘋果授權制造商分發他們的操作系統。我想讀一下備忘錄的最後部分，讓你們知道這份備忘錄是多麼的有洞察力。<em>[00:09:30]</em> 蓋茨寫道：“如果沒有其他個人電腦製造商的支持，蘋果現在不可能讓他們的創新技術成為標準。蘋果必須開放麥金塔的架構，以獲得快速發展和建立標準所需的支持。”換句話説，你們不要再自己玩自己的了。你們必須有與他人合作的意願。你們必須與開發者合作。</p><p><em>[00:10:00]</em> 多年後你依然可以看到這條哲學思想，當微軟首席執行官<ruby>史蒂夫·鮑爾默<rt>Steve Ballmer</rt></ruby>上台做主題演講時，他開始大喊：“開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者。”你懂我的意思了吧。微軟喜歡開發人員。雖然目前（LCTT 譯註：本播客發佈於 2018 年初）他們不打算與這些開發人員共享源代碼，但是他們確實想建立起整個合作伙伴生態系統。<em>[00:10:30]</em> 而當比爾·蓋茨建議蘋果公司也這麼做時，如你可能已經猜到的，這個想法就被蘋果公司拋到了九霄雲外。他們的關係產生了間隙，五個月後，微軟發佈了 Windows 1.0。戰爭開始了。</p><blockquote><p>開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者，開發者。</p></blockquote><p><em>[00:11:00]</em> 你正在收聽的是來自紅帽公司的原創播客《代碼英雄》。本集是第一集，我們將回到過去，重温操作系統戰爭的史詩故事，我們將會發現，科技巨頭之間的戰爭是如何為我們今天所生活的開源世界掃清道路的</p><p>好的，讓我們先來個背景故事吧。如果你已經聽過了，那麼請原諒我，但它很經典。當時是 1979 年，史蒂夫·喬布斯開車去<ruby>帕洛阿爾託<rt>Palo Alto</rt></ruby>的<ruby>施樂公園研究中心<rt>Xerox Park research center</rt></ruby>。<em>[00:11:30]</em> 那裏的工程師一直在為他們所謂的圖形用户界面開發一系列的元素。也許你聽説過。它們有菜單、滾動條、按鈕、文件夾和重疊的窗口。這是對計算機界面的一個美麗的新設想。這是前所未有的。作家兼記者 Steve Levy 會談到它的潛力。</p><p><strong>Steven Levy：</strong><em>[00:12:00]</em> 對於這個新界面來説，有很多令人激動的地方，它比以前的交互界面更友好，以前用的所謂的命令列 —— 你和電腦之間的交互方式跟現實生活中的交互方式完全不同。鼠標和電腦上的圖像讓你可以做到像現實生活中的交互一樣，你可以像指向現實生活中的東西一樣指向電腦上的東西。這讓事情變得簡單多了。你無需要記住所有那些命令。</p><p><strong>Saron Yitbarek：</strong><em>[00:12:30]</em> 不過，施樂的高管們並沒有意識到他們正坐在金礦上。一如既往地，工程師比主管們更清楚它的價值。因此那些工程師，當被要求向喬布斯展示所有這些東西是如何工作時，有點緊張。然而這是畢竟是高管的命令。喬布斯覺得，用他的話來説，“這個產品天才本來能夠讓施樂公司壟斷整個行業，可是它最終會被公司的經營者毀掉，因為他們對產品的好壞沒有概念。”<em>[00:13:00]</em> 這話有些苛刻，但是，喬布斯帶着一卡車施樂高管錯過的想法離開了會議。這幾乎包含了他需要革新桌面計算體驗的所有東西。1983 年，蘋果發佈了 Lisa 電腦，1984 年又發佈了 Mac 電腦。這些設備的創意是抄襲自施樂公司的。</p><p>讓我感興趣的是，喬布斯對控訴他偷了圖形用户界面的反應。他對此很冷靜。他引用畢加索的話：“好的藝術家抄襲，偉大的藝術家偷竊。”他告訴一位記者，“我們總是無恥地竊取偉大的創意。”<em>[00:13:30]</em> 偉大的藝術家偷竊，好吧，我的意思是，我們説的並不是嚴格意義上的“偷竊”。沒人拿到了專有的源代碼並公然將其集成到他們自己的操作系統中去。這要更温和些，更像是創意的借用。這就難控制的多了，就像喬布斯自己即將學到的那樣。傳奇的軟件奇才、真正的代碼英雄 Andy Hertzfeld 就是麥金塔開發團隊的最初成員。</p><p><strong>Andy Hertzfeld：</strong><em>[00:14:00]</em> 是的，微軟是我們的第一個麥金塔電腦軟件合作伙伴。當時，我們並沒有把他們當成是競爭對手。他們是蘋果之外，我們第一家交付麥金塔電腦原型的公司。我通常每週都會和微軟的技術主管聊一次。他們是第一個嘗試我們所編寫軟件的外部團隊。<em>[00:14:30]</em> 他們給了我們非常重要的反饋，總的來説，我認為我們的關係非常好。但我也注意到，在我與技術主管的交談中，他開始問一些系統實現方面的問題，而他本無需知道這些，我覺得，他們想要複製麥金塔電腦。我很早以前就向史蒂夫·喬布斯反饋過這件事，但在 1983 年秋天，這件事達到了高潮。<em>[00:15:00]</em> 我們發現，他們在 1983 年 11 月的 COMDEX 上發佈了 Windows，但卻沒有提前告訴我們。對此史蒂夫·喬布斯勃然大怒。他認為那是一種背叛。</p><p><strong>Saron Yitbarek：</strong>隨着新版 Windows 的發佈，很明顯，微軟從蘋果那裏學到了蘋果從施樂那裏學來的所有想法。喬布斯很易怒。他的關於偉大藝術家如何偷竊的畢加索名言被別人學去了，而且恐怕蓋茨也正是這麼做的。<em>[00:15:30]</em> 據報道，當喬布斯怒斥蓋茨偷了他們的東西時，蓋茨回應道：“史蒂夫，我覺得這更像是我們都有一個叫施樂的富有鄰居，我闖進他家偷電視機，卻發現你已經偷過了”。蘋果最終以竊取 GUI 的外觀和風格為名起訴了微軟。這個案子持續了好幾年，但是在 1993 年，第 9 巡迴上訴法院的一名法官最終站在了微軟一邊。<em>[00:16:00]</em> Vaughn Walker 法官宣佈外觀和風格不受版權保護。這是非常重要的。這一決定讓蘋果在無法壟斷桌面計算的界面。很快，蘋果短暫的領先優勢消失了。以下是 Steven Levy 的觀點。</p><p><strong>Steven Levy：</strong>他們之所以失去領先地位，不是因為微軟方面竊取了知識產權，而是因為他們無法鞏固自己在上世紀 80 年代擁有的更好的操作系統的優勢。坦率地説，他們的電腦索價過高。<em>[00:16:30]</em> 因此微軟從 20 世紀 80 年代中期開始開發 Windows 系統，但直到 1990 年開發出的 Windows 3，我想，它才真正算是一個為黃金時期做好準備的版本，才真正可供大眾使用。<em>[00:17:00]</em> 從此以後，微軟能夠將數以億計的用户遷移到圖形界面，而這是蘋果無法做到的。雖然蘋果公司有一個非常好的操作系統，但是那已經是 1984 年的產品了。</p><p><strong>Saron Yitbarek：</strong>現在微軟主導着操作系統的戰場。他們佔據了 90% 的市場份額，並且針對各種各樣的個人電腦進行了標準化。操作系統的未來看起來會由微軟掌控。此後發生了什麼？<em>[00:17:30]</em> 1997 年，波士頓 Macworld 博覽會上，你看到了一個幾近破產的蘋果，一個謙遜的多的史蒂夫·喬布斯走上舞台，開始談論夥伴關係的重要性，特別是他們與微軟的新型合作伙伴關係。史蒂夫·喬布斯呼籲雙方緩和關係，停止火拼。微軟將擁有巨大的市場份額。從表面看，我們可能會認為世界和平了。但當利益如此巨大時，事情就沒那麼簡單了。<em>[00:18:00]</em> 就在蘋果和微軟在數十年的爭鬥中傷痕累累、最終敗退到死角之際，一名 21 歲的芬蘭計算機科學專業學生出現了。幾乎是偶然地，他徹底改變了一切。</p><p>我是 Saron Yitbarek，這裏是代碼英雄。</p><p>正當某些科技巨頭正忙着就專有軟件相互攻擊時，自由軟件和開源軟件的新領軍者如雨後春筍般湧現。<em>[00:18:30]</em> 其中一位優勝者就是<ruby>理查德·斯托爾曼<rt>Richard Stallman</rt></ruby>。你也許對他的工作很熟悉。他想要有自由軟件和自由社會。這就像言論自由一樣的<ruby>自由<rt>free</rt></ruby>，而不是像免費啤酒一樣的<ruby>免費<rt>free</rt></ruby>。早在 80 年代，斯托爾曼就發現，除了昂貴的專有操作系統（如 UNIX）外，就沒有其他可行的替代品。因此他決定自己做一個。斯托爾曼的<ruby>自由軟件基金會<rt>Free Software Foundation</rt></ruby>開發了 GNU，當然，它的意思是 “GNU&#39;s not UNIX”。它將是一個像 UNIX 一樣的操作系統，但不包含所有的 UNIX 代碼，而且用户可以自由共享。</p><p><em>[00:19:00]</em> 為了讓你體會到上世紀 80 年代自由軟件概念的重要性，從不同角度來説擁有 UNIX 代碼的兩家公司，<ruby>AT&amp;T 貝爾實驗室<rt>AT&amp;T Bell Laboratories</rt></ruby>以及<ruby>UNIX 系統實驗室<rt>UNIX System Laboratories</rt></ruby>威脅將會起訴任何看過 UNIX 源代碼後又創建自己操作系統的人。這些人是次級專利所屬。<em>[00:19:30]</em> 用這兩家公司的話來説，所有這些程序員都在“精神上受到了污染”，因為他們都見過 UNIX 代碼。在 UNIX 系統實驗室和<ruby>伯克利軟件設計公司<rt>Berkeley Software Design</rt></ruby>之間的一個著名的法庭案例中，有人認為任何功能類似的系統，即使它本身沒有使用 UNIX 代碼，也侵犯版權。Paul Jones 當時是一名開發人員。他現在是數字圖書館 ibiblio.org 的主管。</p><p><strong>Paul Jones：</strong><em>[00:20:00]</em> 任何看過代碼的人都受到了精神污染是他們的觀點。因此幾乎所有在安裝有與 UNIX 相關操作系統的電腦上工作過的人以及任何在計算機科學部門工作的人都受到精神上的污染。因此，在 USENIX 的一年裏，我們都得到了一寫帶有紅色字母的白色小別針，上面寫着“精神受到了污染”。我們很喜歡帶着這些別針到處走，以表達我們跟着貝爾實驗室混，因為我們的精神受到了污染。</p><p><strong>Saron Yitbarek：</strong><em>[00:20:30]</em> 整個世界都被精神污染了。想要保持純粹、保持事物的美好和專有的舊哲學正變得越來越不現實。正是在這被污染的現實中，歷史上最偉大的代碼英雄之一誕生了，他是一個芬蘭男孩，名叫<ruby>林納斯·託瓦茲<rt>Linus Torvalds</rt></ruby>。如果這是《星球大戰》，那麼林納斯·託瓦茲就是我們的<ruby>盧克·天行者<rt>Luke Skywalker</rt></ruby>。他是赫爾辛基大學一名温文爾雅的研究生。<em>[00:21:00]</em> 有才華，但缺乏大志。典型的被逼上梁山的英雄。和其他年輕的英雄一樣，他也感到沮喪。他想把 386 處理器整合到他的新電腦中。他對自己的 IBM 兼容電腦上運行的 MS-DOS 操作系統並不感冒，也負擔不起 UNIX 軟件 5000 美元的價格，而只有 UNIX 才能讓他自由地編程。解決方案是託瓦茲在 1991 年春天基於 MINIX 開發了一個名為 Linux 的操作系統內核。他自己的操作系統內核。</p><p><strong>Steven Vaughan-Nichols：</strong><em>[00:21:30]</em> 林納斯·託瓦茲真的只是想找點樂子而已。</p><p><strong>Saron Yitbarek：</strong>Steven Vaughan-Nichols 是 ZDNet.com 的特約編輯，而且他從科技行業出現以來就一直在寫科技行業相關的內容。</p><p><strong>Steven Vaughan-Nichols：</strong>當時有幾個類似的操作系統。他最關注的是一個名叫 MINIX 的操作系統，MINIX 旨在讓學生學習如何構建操作系統。林納斯看到這些，覺得很有趣，但他想建立自己的操作系統。<em>[00:22:00]</em> 所以，它實際上始於赫爾辛基的一個 DIY 項目。一切就這樣開始了，基本上就是一個大孩子在玩耍，學習如何做些什麼。<em>[00:22:30]</em> 但不同之處在於，他足夠聰明、足夠執着，也足夠友好，讓所有其他人都參與進來，然後他開始把這個項目進行到底。27 年後，這個項目變得比他想像的要大得多。</p><p><strong>Saron Yitbarek：</strong>到 1991 年秋季，託瓦茲發佈了 10000 行代碼，世界各地的人們開始評頭論足，然後進行優化、添加和修改代碼。<em>[00:23:00]</em> 對於今天的開發人員來説，這似乎很正常，但請記住，在那個時候，像這樣的開放協作是對微軟、蘋果和 IBM 已經做的很好的整個專有系統的道德侮辱。隨後這種開放性被奉若神明。託瓦茲將 Linux 置於 GNU 通用公共許可證（GPL）之下。曾經保障斯托爾曼的 GNU 系統自由的許可證現在也將保障 Linux 的自由。Vaughan-Nichols 解釋道，這種融入到 GPL 的重要性怎麼強調都不過分，它基本上能永遠保證軟件的自由和開放性。</p><p><strong>Steven Vaughan-Nichols：</strong><em>[00:23:30]</em> 事實上，根據 Linux 所遵循的許可協議，即 GPL 第 2 版，如果你想販賣 Linux 或者向全世界展示它，你必須與他人共享代碼，所以如果你對其做了一些改進，僅僅給別人使用是不夠的。事實上你必須和他們分享所有這些變化的具體細節。然後，如果這些改進足夠好，就會被 Linux 所吸收。</p><p><strong>Saron Yitbarek：</strong><em>[00:24:00]</em> 事實證明，這種公開的方式極具吸引力。<ruby>埃裏克·雷蒙德<rt>Eric Raymond</rt></ruby> 是這場運動的早期傳道者之一，他在他那篇著名的文章中寫道：“微軟和蘋果這樣的公司一直在試圖建造軟件大教堂，而 Linux 及類似的軟件則提供了一個由不同議程和方法組成的巨大集市，集市比大教堂有趣多了。”</p><p><strong>tormy Peters：</strong>我認為在那個時候，真正吸引人的是人們終於可以把控自己的世界了。</p><p><strong>Saron Yitbarek：</strong>Stormy Peters 是一位行業分析師，也是自由和開源軟件的倡導者。</p><p><strong>Stormy Peters：</strong><em>[00:24:30]</em> 當開源軟件第一次出現的時候，所有的操作系統都是專有的。如果不使用專有軟件，你甚至不能添加打印機，你不能添加耳機，你不能自己開發一個小型硬件設備，然後讓它在你的筆記本電腦上運行。你甚至不能放入 DVD 並複製它，因為你不能改變軟件，即使你擁有這張 DVD，你也無法複製它。<em>[00:25:00]</em> 你無法控制你購買的硬件/軟件系統。你不能從中創造出任何新的、更大的、更好的東西。這就是為什麼開源操作系統在一開始就如此重要的原因。我們需要一個開源協作環境，在那裏我們可以構建更大更好的東西。</p><p><strong>Saron Yitbarek：</strong>請注意，Linux 並不是一個純粹的平等主義烏托邦。林納斯·託瓦茲不會批准對內核的所有修改，而是主導了內核的變更。他安排了十幾個人來管理內核的不同部分。<em>[00:25:30]</em> 這些人也會信任自己下面的人，以此類推，形成信任金字塔。變化可能來自任何地方，但它們都是經過判斷和策劃的。</p><p>然而，考慮到到林納斯的 DIY 項目一開始是多麼的簡陋和隨意，這項成就令人十分驚訝。他完全不知道自己就是這一切中的盧克·天行者。當時他只有 21 歲，一半的時間都在編程。但是當魔盒第一次被打開，人們開始給他反饋。<em>[00:26:00]</em> 幾十個，然後幾百個，成千上萬的貢獻者。有了這樣的眾包基礎，Linux 很快就開始成長。真的成長得很快。甚至最終引起了微軟的注意。他們的首席執行官<ruby>史蒂夫·鮑爾默<rt>Steve Ballmer</rt></ruby>將 Linux 稱為是“一種癌症，從知識產權得角度來看，它傳染了接觸到得任何東西 ”。Steven Levy 將會描述 Ballmer 的由來。</p><p><strong>Steven Levy：</strong><em>[00:26:30]</em> 一旦微軟真正鞏固了它的壟斷地位，而且它也確實被聯邦法院判定為壟斷，他們將會對任何可能對其構成威脅的事情做出強烈反應。因此，既然他們對軟件收費，很自然得，他們將自由軟件得出現看成是一種癌症。他們試圖提出一個知識產權理論，來解釋為什麼這對消費者不利。</p><p><strong>Saron Yitbarek：</strong><em>[00:27:00]</em> Linux 在不斷傳播，微軟也開始擔心起來。到了 2006 年，Linux 成為僅次於 Windows 的第二大常用操作系統，全球約有 5000 名開發人員在使用它。5000 名開發者。還記得比爾·蓋茨給蘋果公司的備忘錄嗎？在那份備忘錄中，他向蘋果公司的員工們論述了與他人合作的重要性。事實證明，開源將把夥伴關係的概念提升到一個全新的水平，這是比爾·蓋茨從未預見到的。</p><p><em>[00:27:30]</em> 我們一直在談論操作系統之間的大戰，但是到目前為止，並沒有怎麼提到無名英雄和開發者們。在下次的代碼英雄中，情況就不同了。第二集講的是操作系統大戰的第二部分，是關於 Linux 崛起的。業界醒悟過來，認識到了開發人員的重要性。這些開源反叛者變得越來越強大，戰場從桌面轉移到了服務器領域。<em>[00:28:00]</em> 這裏有商業間諜活動、新的英雄人物，還有科技史上最不可思議的改變。這一切都在操作系統大戰的後半集內達到了高潮。</p>",51)),t("p",null,[r[8]||(r[8]=e("要想免費自動獲得新一集的代碼英雄，請點擊訂閲蘋果播客、Spotify、谷歌 Play，或其他應用獲取該播客。在這一季剩下的時間裏，我們將參觀最新的戰場，相互爭鬥的版圖，這裏是下一代的代碼英雄留下印記的地方。",-1)),r[9]||(r[9]=t("em",null,"[00:28:30]",-1)),r[10]||(r[10]=e(" 更多信息，請訪問 ",-1)),o(n,{href:"https://redhat.com/commandlineheroes"},{default:m(()=>[...r[7]||(r[7]=[e("https://redhat.com/commandlineheroes",-1)])]),_:1}),r[11]||(r[11]=e(" 。我是 Saron Yitbarek。下次之前，繼續編碼。",-1))]),r[31]||(r[31]=t("hr",null,null,-1)),t("p",null,[r[13]||(r[13]=e("via: ",-1)),o(n,{href:"https://www.redhat.com/en/command-line-heroes/season-1/os-wars-part-1"},{default:m(()=>[...r[12]||(r[12]=[e("https://www.redhat.com/en/command-line-heroes/season-1/os-wars-part-1",-1)])]),_:1})]),t("p",null,[r[18]||(r[18]=e("作者：",-1)),o(n,{href:"https://www.redhat.com"},{default:m(()=>[...r[14]||(r[14]=[e("redhat",-1)])]),_:1}),r[19]||(r[19]=e(" 選題：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:m(()=>[...r[15]||(r[15]=[e("lujun9972",-1)])]),_:1}),r[20]||(r[20]=e(" 譯者：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:m(()=>[...r[16]||(r[16]=[e("lujun9972",-1)])]),_:1}),r[21]||(r[21]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:m(()=>[...r[17]||(r[17]=[e("wxy",-1)])]),_:1})]),t("p",null,[r[24]||(r[24]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:m(()=>[...r[22]||(r[22]=[e("LCTT",-1)])]),_:1}),r[25]||(r[25]=e(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:m(()=>[...r[23]||(r[23]=[e("Linux中國",-1)])]),_:1}),r[26]||(r[26]=e(" 榮譽推出",-1))])])}const N=s(i,[["render",g]]);export{k as __pageData,N as default};
